// State
        let stream = null;
        let isBenchmarking = false;
        let selectedProfile = '1080p';
        let frameCount = 0;
        let droppedCount = 0;
        let lastFrameTimestamp = 0;
        let frameDeltas = [];
        let rvfcHandle = null;
        let rafHandle = null;
        let lastResult = {
            fps: 0,
            resolution: '--',
            jitter: 0,
            droppedPct: 0
        };

        // Elements
        const video = document.getElementById('benchmark-video');
        const placeholder = document.getElementById('video-placeholder');
        const hud = document.getElementById('video-hud');
        const hudFps = document.getElementById('hud-fps-text');
        const hudRes = document.getElementById('hud-res-text');
        const hudExposure = document.getElementById('hud-exposure-warning');
        const btnToggle = document.getElementById('btn-toggle-cam');
        const btnText = document.getElementById('cam-btn-text');
        const metricFps = document.getElementById('metric-fps');
        const metricFpsSub = document.getElementById('metric-fps-sub');
        const metricRes = document.getElementById('metric-res');
        const metricAspect = document.getElementById('metric-aspect');
        const metricJitter = document.getElementById('metric-jitter');
        const metricStability = document.getElementById('metric-stability');
        const metricDropped = document.getElementById('metric-dropped');
        const metricFramesCount = document.getElementById('metric-frames-count');
        const deviceLabel = document.getElementById('device-label');

        function setResolutionProfile(profile) {
            selectedProfile = profile;
            document.querySelectorAll('.res-profile-btn').forEach(btn => {
                if (btn.getAttribute('data-profile') === profile) {
                    btn.className = 'res-profile-btn px-3 py-2 rounded-xl text-xs font-bold transition border bg-indigo-600 border-indigo-600 text-white shadow-sm';
                    btn.querySelector('span').className = 'block text-[9px] font-normal text-indigo-100';
                } else {
                    btn.className = 'res-profile-btn px-3 py-2 rounded-xl text-xs font-bold transition border bg-white border-slate-200 text-slate-600 hover:border-indigo-400';
                    btn.querySelector('span').className = 'block text-[9px] font-normal text-slate-400';
                }
            });
            if (isBenchmarking) {
                stopWebcam();
                startWebcam();
            }
        }

        function getConstraints() {
            if (selectedProfile === '4k') {
                return { video: { width: { ideal: 3840 }, height: { ideal: 2160 }, frameRate: { ideal: 60 } } };
            } else if (selectedProfile === '720p') {
                return { video: { width: { ideal: 1280 }, height: { ideal: 720 }, frameRate: { ideal: 60 } } };
            } else if (selectedProfile === 'max') {
                return { video: { width: { ideal: 4096 }, height: { ideal: 3072 }, frameRate: { ideal: 120 } } };
            }
            // 1080p default
            return { video: { width: { ideal: 1920 }, height: { ideal: 1080 }, frameRate: { ideal: 60 } } };
        }

        async function startWebcam() {
            try {
                if (!navigator.mediaDevices || !navigator.mediaDevices.getUserMedia) {
                    alert("Your browser does not support the Web MediaDevices Camera API.");
                    return;
                }
                btnText.innerText = "Connecting Sensor...";
                stream = await navigator.mediaDevices.getUserMedia(getConstraints());
                video.srcObject = stream;
                await video.play();

                const track = stream.getVideoTracks()[0];
                const settings = track.getSettings ? track.getSettings() : {};
                if (settings.label || track.label) {
                    deviceLabel.innerText = track.label || "Hardware Camera";
                }

                // Update UI to active
                placeholder.classList.add('hidden');
                video.classList.remove('hidden');
                hud.classList.remove('hidden');
                btnText.innerText = "Stop Benchmark";
                const camIconEl = document.getElementById("cam-icon");
                if (camIconEl) {
                    camIconEl.innerHTML = `<svg class="w-4 h-4 animate-pulse" fill="currentColor" viewBox="0 0 24 24"><rect x="6" y="6" width="12" height="12" rx="2"></rect></svg>`;
                }
                btnToggle.className = "px-5 py-2.5 rounded-xl text-xs font-bold bg-red-600 hover:bg-red-700 text-white transition shadow-sm flex items-center gap-2";
                isBenchmarking = true;

                // Reset metrics
                frameCount = 0;
                droppedCount = 0;
                lastFrameTimestamp = performance.now();
                frameDeltas = [];

                // Start Frame Loop
                if ('requestVideoFrameCallback' in HTMLVideoElement.prototype) {
                    onVideoFrameCallback();
                } else {
                    onRafLoop();
                }
            } catch (err) {
                console.error("Camera access failed", err);
                alert("Camera Access Error: " + (err.message || "Permission was denied or camera is in use by another application."));
                stopWebcam();
            }
        }

        function stopWebcam() {
            isBenchmarking = false;
            if (rvfcHandle && video.cancelVideoFrameCallback) {
                video.cancelVideoFrameCallback(rvfcHandle);
                rvfcHandle = null;
            }
            if (rafHandle) {
                cancelAnimationFrame(rafHandle);
                rafHandle = null;
            }
            if (stream) {
                stream.getTracks().forEach(t => t.stop());
                stream = null;
            }
            video.srcObject = null;
            video.classList.add('hidden');
            placeholder.classList.remove('hidden');
            hud.classList.add('hidden');
            hudExposure.classList.add('hidden');
            btnText.innerText = "Start Benchmark";
            const camIconEl = document.getElementById("cam-icon");
            if (camIconEl) {
                camIconEl.innerHTML = `<svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M15 10l4.553-2.276A1 1 0 0121 8.618v6.764a1 1 0 01-1.447.894L15 14M5 18h8a2 2 0 002-2V8a2 2 0 00-2-2H5a2 2 0 00-2 2v8a2 2 0 002 2z"></path></svg>`;
            }
            btnToggle.className = "px-5 py-2.5 rounded-xl text-xs font-bold bg-indigo-600 hover:bg-indigo-700 text-white transition shadow-sm flex items-center gap-2";
        }

        function toggleWebcamBenchmark() {
            if (isBenchmarking) {
                stopWebcam();
            } else {
                startWebcam();
            }
        }

        function onVideoFrameCallback(now, metadata) {
            if (!isBenchmarking) return;
            const currentNow = now || performance.now();
            recordFrameTime(currentNow);
            rvfcHandle = video.requestVideoFrameCallback(onVideoFrameCallback);
        }

        function onRafLoop() {
            if (!isBenchmarking) return;
            const currentNow = performance.now();
            recordFrameTime(currentNow);
            rafHandle = requestAnimationFrame(onRafLoop);
        }

        function recordFrameTime(now) {
            if (lastFrameTimestamp > 0) {
                const delta = now - lastFrameTimestamp;
                if (delta > 2) { // Filter zero/sub-millisecond redundant ticks
                    frameDeltas.push(delta);
                    if (frameDeltas.length > 60) frameDeltas.shift();
                    frameCount++;

                    // Check for dropped frame (e.g. interval > 1.7x average)
                    const avgInterval = frameDeltas.reduce((a, b) => a + b, 0) / frameDeltas.length;
                    if (delta > avgInterval * 1.7) {
                        droppedCount++;
                    }
                }
            }
            lastFrameTimestamp = now;

            // Update stats every 10 frames
            if (frameCount % 6 === 0) {
                updateBenchmarkDisplays();
            }
        }

        function updateBenchmarkDisplays() {
            if (!frameDeltas.length) return;
            const avgDelta = frameDeltas.reduce((a, b) => a + b, 0) / frameDeltas.length;
            const currentFps = 1000 / avgDelta;

            // Standard deviation / jitter
            const variance = frameDeltas.reduce((sum, d) => sum + Math.pow(d - avgDelta, 2), 0) / frameDeltas.length;
            const jitterMs = Math.sqrt(variance);

            const droppedPct = frameCount > 0 ? ((droppedCount / frameCount) * 100).toFixed(1) : '0.0';

            const w = video.videoWidth || 0;
            const h = video.videoHeight || 0;

            lastResult = {
                fps: currentFps,
                resolution: `${w} × ${h}`,
                jitter: jitterMs,
                droppedPct: droppedPct
            };

            metricFps.innerText = currentFps.toFixed(1);
            hudFps.innerText = `${currentFps.toFixed(1)} FPS`;

            if (currentFps >= 55) {
                metricFpsSub.innerText = "High-Speed 60 FPS Fluid";
                metricFpsSub.className = "block text-[9px] text-emerald-600 font-bold mt-0.5";
                hudExposure.classList.add('hidden');
            } else if (currentFps >= 27) {
                metricFpsSub.innerText = "Standard 30 FPS Normal";
                metricFpsSub.className = "block text-[9px] text-indigo-600 font-semibold mt-0.5";
                if (selectedProfile === '1080p' || selectedProfile === '4k') {
                    hudExposure.classList.remove('hidden');
                }
            } else {
                metricFpsSub.innerText = "Stuttering (< 24 FPS)";
                metricFpsSub.className = "block text-[9px] text-red-600 font-bold mt-0.5";
                hudExposure.classList.remove('hidden');
            }

            if (w > 0 && h > 0) {
                metricRes.innerText = `${w} × ${h}`;
                hudRes.innerText = `${w}×${h}`;
                const gcdVal = (a, b) => b === 0 ? a : gcdVal(b, a % b);
                const divisor = gcdVal(w, h);
                const aspectStr = (w/divisor <= 16 && h/divisor <= 9) ? `${w/divisor}:${h/divisor}` : (w/h).toFixed(2) + ':1';
                metricAspect.innerText = `${aspectStr} Aspect`;
            }

            metricJitter.innerText = `${jitterMs.toFixed(1)} ms`;
            if (jitterMs < 4) {
                metricStability.innerText = "Stability: Excellent";
                metricStability.className = "block text-[9px] text-emerald-600 font-bold mt-0.5";
            } else if (jitterMs < 10) {
                metricStability.innerText = "Stability: Normal";
                metricStability.className = "block text-[9px] text-slate-500 font-semibold mt-0.5";
            } else {
                metricStability.innerText = "Stability: High Jitter";
                metricStability.className = "block text-[9px] text-amber-600 font-bold mt-0.5";
            }

            metricDropped.innerText = `${droppedPct}%`;
            metricFramesCount.innerText = `${frameCount} frames`;
        }

        function captureTestSnapshot() {
            if (!video.videoWidth) {
                alert("Please start the benchmark first to capture a test frame.");
                return;
            }
            const canvas = document.getElementById('offscreen-canvas');
            canvas.width = video.videoWidth;
            canvas.height = video.videoHeight;
            const ctx = canvas.getContext('2d');
            ctx.drawImage(video, 0, 0, canvas.width, canvas.height);

            const dataUrl = canvas.toDataURL('image/png');
            const link = document.createElement('a');
            link.download = `webcam_test_${video.videoWidth}x${video.videoHeight}_${Math.round(lastResult.fps)}fps.png`;
            link.href = dataUrl;
            link.click();
        }

        function copyWebcamScorecard() {
            const report = `=== ToolkitGen Webcam Hardware & FPS Benchmark ===\n` +
                `Date: ${new Date().toLocaleString()}\n` +
                `Camera Device: ${deviceLabel.innerText}\n` +
                `Delivered Resolution: ${lastResult.resolution}\n` +
                `Delivered Frame Rate: ${lastResult.fps.toFixed(1)} FPS\n` +
                `Frame Delivery Jitter: ${lastResult.jitter.toFixed(1)} ms\n` +
                `Dropped Frame Rate: ${lastResult.droppedPct}%\n` +
                `Total Tested Frames: ${frameCount}\n` +
                `Diagnostic URL: https://toolkitgen.com/tool/webcam_hardware_fps_test`;

            if (navigator.clipboard) {
                navigator.clipboard.writeText(report).then(() => {
                    alert("Webcam benchmark report copied to clipboard!");
                }).catch(() => prompt("Copy your report:", report));
            } else {
                prompt("Copy your report:", report);
            }
        }
